window.ScripturaLexicons.BDAG_PART_0312 = {"source":"BDAG","searchAnchorId":"bdag-search-anchor","entryAnchorId":"bdag-entry-anchor","rowsHtml":"<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-01\" data-source=\"BDAG\" data-search=\"πυκτεύω verbo lutar com os punhos, boxear BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυκτεύω</td><td>verbo</td><td>lutar com os punhos, boxear</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-02\" data-source=\"BDAG\" data-search=\"πύλη, ης, ἡ substantivo feminino porta, portão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πύλη, ης, ἡ</td><td>substantivo feminino</td><td>porta, portão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-03\" data-source=\"BDAG\" data-search=\"πυλών, ῶνος, ὁ substantivo masculino portal, entrada, portão BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυλών, ῶνος, ὁ</td><td>substantivo masculino</td><td>portal, entrada, portão</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-04\" data-source=\"BDAG\" data-search=\"πυνθάνομαι verbo perguntar, informar-se, averiguar BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυνθάνομαι</td><td>verbo</td><td>perguntar, informar-se, averiguar</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-05\" data-source=\"BDAG\" data-search=\"πυξίς, ίδος, ἡ substantivo feminino caixa, recipiente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυξίς, ίδος, ἡ</td><td>substantivo feminino</td><td>caixa, recipiente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-06\" data-source=\"BDAG\" data-search=\"πύον, ου, τό substantivo neutro pus BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πύον, ου, τό</td><td>substantivo neutro</td><td>pus</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-07\" data-source=\"BDAG\" data-search=\"πῦρ, ός, τό substantivo neutro fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πῦρ, ός, τό</td><td>substantivo neutro</td><td>fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-08\" data-source=\"BDAG\" data-search=\"πυρά, ᾶς, ἡ substantivo feminino fogueira, pira BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρά, ᾶς, ἡ</td><td>substantivo feminino</td><td>fogueira, pira</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-09\" data-source=\"BDAG\" data-search=\"πύργος, ου, ὁ substantivo masculino torre, construção agrícola BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πύργος, ου, ὁ</td><td>substantivo masculino</td><td>torre, construção agrícola</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-10\" data-source=\"BDAG\" data-search=\"πυρέσσω verbo sofrer de febre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρέσσω</td><td>verbo</td><td>sofrer de febre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-11\" data-source=\"BDAG\" data-search=\"πυρετός, οῦ, ὁ substantivo masculino febre BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρετός, οῦ, ὁ</td><td>substantivo masculino</td><td>febre</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-12\" data-source=\"BDAG\" data-search=\"πύρινος, η, ον adjetivo ígneo, da cor do fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πύρινος, η, ον</td><td>adjetivo</td><td>ígneo, da cor do fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-13\" data-source=\"BDAG\" data-search=\"πυρκαϊά, ᾶς, ἡ substantivo feminino pira funerária BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρκαϊά, ᾶς, ἡ</td><td>substantivo feminino</td><td>pira funerária</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-14\" data-source=\"BDAG\" data-search=\"πυροειδής, ές adjetivo vermelho como fogo, vermelho vivo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυροειδής, ές</td><td>adjetivo</td><td>vermelho como fogo, vermelho vivo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-15\" data-source=\"BDAG\" data-search=\"πυρός, οῦ, ὁ substantivo masculino trigo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρός, οῦ, ὁ</td><td>substantivo masculino</td><td>trigo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-16\" data-source=\"BDAG\" data-search=\"πυρόω verbo incendiar, arder, tornar incandescente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρόω</td><td>verbo</td><td>incendiar, arder, tornar incandescente</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-17\" data-source=\"BDAG\" data-search=\"πυρράζω verbo ser vermelho como fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρράζω</td><td>verbo</td><td>ser vermelho como fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-18\" data-source=\"BDAG\" data-search=\"πυρρός, ά, όν adjetivo vermelho como fogo BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πυρρός, ά, όν</td><td>adjetivo</td><td>vermelho como fogo</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-19\" data-source=\"BDAG\" data-search=\"Πύρρος, ου, ὁ nome próprio masculino Pirro BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">Πύρρος, ου, ὁ</td><td>nome próprio masculino</td><td>Pirro</td><td><span class=\"source-pill\">BDAG</span></td></tr>\n<tr class=\"search-row\" data-dictionary=\"grego\" data-target=\"entry-bdag-0312-20\" data-source=\"BDAG\" data-search=\"πύρωσις, εως, ἡ substantivo feminino combustão, provação ardente BDAG\" tabindex=\"0\"><td class=\"table-lemma greek\">πύρωσις, εως, ἡ</td><td>substantivo feminino</td><td>combustão, provação ardente</td><td><span class=\"source-pill\">BDAG</span></td></tr>","cardsHtml":"<article class=\"entry-card\" id=\"entry-bdag-0312-01\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυκτεύω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυκτεύω</span> (<span class=\"greek\">πύκτης</span> ‘pugilista’; X., Pla. e outros; Dio Chrys. 14 [31], 156; Kaibel 291, 1) lutar com os punhos, boxear, metaforicamente (Reader, Polemo 342f; APapathomas, NTS 43, ’97, 237f [literatura n. 63; para pap. com o substantivo <span class=\"greek\">πύκτης</span> v. n. 65]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.9.26\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 9:26</a>.—DELG s.v. <span class=\"greek\">πύξ</span> IV. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-02\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύλη, ης, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πύλη</span>, <span class=\"greek\">ης</span>, <span class=\"greek\">ἡ</span> (Hom.+; empréstimo na literatura rabínica) portão, porta</p><p class=\"entry-text\">ⓐ lit., acerca dos portões das cidades (X., Mem. 3, 9, 7; Maximus Tyr. 15, 3a; Polyaenus 7, 13; Jos., Vi. 108) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.7.12\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 7:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.9.24\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 9:24</a> (uma situação como em Appian, Bell. Civ. 4, 12 §48 <span class=\"greek\">αἱ</span> <span class=\"greek\">πύλαι</span> <span class=\"greek\">κατείχοντο</span> na busca de homens proscritos). <span class=\"greek\">ἔξω</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πύλης</span> fora do portão, fora da cidade 16:13; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.13.12\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 13:12</a> (a crucificação fora da cidade era a prática habitual: Artem. 2, 53 p. 152, 17); GJs 4:4 (v. deStrycker sobre a passagem). Acerca de um portão do templo em Jerusalém <span class=\"greek\">ἡ</span> <span class=\"greek\">ὡραία</span> <span class=\"greek\">πύλη</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 3:10</a> (v. <span class=\"greek\">ὡραῖος</span> 2). A prisão tem <span class=\"greek\">τὴν</span> <span class=\"greek\">πύλην</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">σιδηρᾶν</span> 12:10 (v. Jos., Bell. 7, 245). <span class=\"greek\">πύλας</span> <span class=\"greek\">χαλκᾶς</span> <span class=\"greek\">συντρίψω</span> B 11:4 (Ps 106:16). Numa visão de uma rocha com um portão (entrada) Hs 9, 2, 2f; 9, 3, 1f; 4; 9, 4, 1f; 5f e 8; 9, 5, 3; 9, 6, 7; 9, 12, 1–6; 9, 13, 6; 9, 14, 4; 9, 15, 5. Sobre as <span class=\"greek\">πύλαι</span> <span class=\"greek\">ᾅδου</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.18\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:18</a> v. <span class=\"greek\">ᾅδης</span> 1 e a literatura s.v. <span class=\"greek\">κλείς</span> 1 e <span class=\"greek\">πέτρα</span> 1b, também JBernard, The Gates of Hades: Exp. 8th ser., 11, 1916, 401–9; REppel, Aux sources de la tradition Chrétienne: MGoguel Festschr. ’50, 71–73; OBetz, ZNW 48, ’57, 49–77 (Qumran; cf. 1QH 6:24); CBrown, SBLSP 26, ’87, 357–67.</p><p class=\"entry-text\">ⓑ em linguagem figurada (cf. Pind., O. 6, 27 ‘porta do canto’; Soph., Fgm. 360 TGF ‘porta da alma’), acerca da <span class=\"greek\">στενὴ</span> <span class=\"greek\">πύλη</span> que conduz à vida <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.7.13\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 7:13a</a>, 14 (v. TestAbr A 11 p. 89, 1f [Stone p. 26], B 9 p. 113, 15 [Stone p. 74]; SibOr 2, 150 <span class=\"greek\">π</span>. <span class=\"greek\">ζωῆς</span>); v. também v. 13b; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:24</a> v.l. (cf. Cebes 15, 1–3, o caminho difícil e a porta estreita, que proporcionam uma <span class=\"greek\">ἀνάβασις</span> <span class=\"greek\">στενὴ</span> <span class=\"greek\">πάνυ</span> à <span class=\"greek\">ἀληθινὴ</span> <span class=\"greek\">παιδεία</span>). <span class=\"greek\">π</span>. <span class=\"greek\">δικαιοσύνης</span> a porta da justiça 1 Cl 48:2a; v. também v. 2b (Ps 117:19). Também <span class=\"greek\">ἡ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">δικαιοσύνῃ</span> (<span class=\"greek\">πύλη</span>) v. 4b. Esta porta é também chamada <span class=\"greek\">ἡ</span> <span class=\"greek\">πύλη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">κυρίου</span> a porta que conduz ao Senhor (ou do Senhor) v. 3 (Ps 117:20). <span class=\"greek\">πολλῶν</span> <span class=\"greek\">πυλῶν</span> <span class=\"greek\">ἀνεῳγυιῶν</span> visto que muitas portas estão abertas v. 4a.—Renehan ’75. B. 466. DELG. M-M. EDNT. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-03\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυλών, ῶνος, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυλών</span>, <span class=\"greek\">ῶνος</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πύλη</span>; Polyb.; Diod S 13, 75, 7; Cebes 1, 2 e outros; ins., pap., LXX, JosAs; GrBar 11:2 [v.l. <span class=\"greek\">ὁ</span> <span class=\"greek\">πύλος</span>]; ApcEsdr 5:13 p. 30, 12 Tdf.; Joseph.; TestZeb 3:6. Empréstimo na literatura rabínica).</p><p class=\"entry-text\">① entrada que contém um portão ou portões, portal, entrada, portão, especialmente acerca dos portais grandes e imponentes à entrada de templos e palácios (Ps.-Aristot., De Mundo 6, 8, 397a; Plut., Tim. 241 [12, 9], contraste <span class=\"greek\">πύλη</span>; ins., LXX; Jos., Bell. 1, 617; 5, 202 <span class=\"greek\">δύο</span> <span class=\"greek\">ἑκάστου</span> <span class=\"greek\">πυλῶνος</span> <span class=\"greek\">θύραι</span> acerca do templo de Herodes=cada portal tinha duas portas), acerca das entradas da Jerusalém celestial (Berosus: 680 Fgm. 8, 140 Jac. [em Jos., C. Ap. 1, 140] acerca dos magníficos portões da cidade de Babilônia; Cephalion [II d.C.]: 93 Fgm. 5 p. 444, 23f Jac., acerca de Tebas <span class=\"greek\">πόλιν</span> <span class=\"greek\">μεγάλην</span> <span class=\"greek\">πάνυ</span>, <span class=\"greek\">δωδεκάπυλον</span>) <span class=\"greek\">οἱ</span> <span class=\"greek\">πυλῶνες</span> <span class=\"greek\">αὐτῆς</span> <span class=\"greek\">οὐ</span> <span class=\"greek\">μὴ</span> <span class=\"greek\">κλεισθῶσιν</span> suas entradas jamais serão fechadas <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.25\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:25</a>; cf. vv. 12ab, 13abcd, 15, 21ab; 22:14. Acerca dos portões de um templo ou de uma cidade <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.14.13\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 14:13</a>. No palácio do rico (cf. Lucian, Nigr. 23) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.16.20\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 16:20</a>; na residência aparentemente elegante de Maria, mãe de João Marcos Ac 12:13: <span class=\"greek\">π</span>. distinto de sua <span class=\"greek\">θύρα</span> (cf. Jos., 5, 202 v. acima). Cf. v. 14ab; também acerca da casa de Simão 10:17. A escolha vocabular contribui para a representação da posição social de Maria e Simão. Acerca de portões de prisão AcPl Ha 3, 22 e 24 (texto restaurado).</p><p class=\"entry-text\">② portal constituído por um pátio anterior, portal, entrada separada da casa por um pátio (IPontEux I2, 32b, 48 [III a.C.]; Polyb. 2, 9, 3; 4, 18, 2; Diod S 1, 47, 1; Ps.-Aristot., De Mundo 6). Pedro sai (<span class=\"greek\">ἐξελθόντα</span>) do pátio (v. 69) e entra <span class=\"greek\">εἰς</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">πυλῶνα</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.26.71\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 26:71</a>, e finalmente sai dele (v. 75).—DELG s.v. <span class=\"greek\">πύλη</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-04\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυνθάνομαι</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυνθάνομαι</span> depoente médio (Hom.+; ins., pap., LXX, En, TestSol, EpArist, Philo, Joseph., Just.) imperf. <span class=\"greek\">ἐπυνθανόμην</span>; 2 aor. <span class=\"greek\">ἐπυθόμην</span> (sobre o emprego dos dois tempos v. B-D-F §328).</p><p class=\"entry-text\">① procurar saber mediante indagação, indagar, perguntar <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> B 13:2 (Gen 25:22). <span class=\"greek\">τὶ</span> <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> (Pla., Gorg. 455c; SIG 1169, 30; 2 Ch 32:31; Jos., C. Ap. 1, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:52</a> (<span class=\"greek\">ἐκείνην</span> v.l.). <span class=\"greek\">τι</span> <span class=\"greek\">ἀκριβέστερον</span> <span class=\"greek\">πυνθάνεσθαι</span> <span class=\"greek\">περὶ</span> <span class=\"greek\">αὐτοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:20</a> (<span class=\"greek\">π</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> como X., An. 5, 5, 25; PHib 72, 11; POxy 930, 12; 1064, 4; Esth 6:4; Just., A I, 31, 2, D. 64, 2.—<span class=\"greek\">π</span>. <span class=\"greek\">ἀκριβέστερον</span> como PPetr II, 16, 13 [III a.C.]). <span class=\"greek\">π</span>. (<span class=\"greek\">καὶ</span> <span class=\"greek\">λέγειν</span>) seguido de pergunta direta <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.17.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 17:19</a> D (Just., D. 36, 6 e outros). Seguido de pergunta indireta (com ou sem <span class=\"greek\">ἄν</span> no opt.; v. B-D-F §386, 1; Pla., Soph. 216d; 2 Macc 3:9; Jos., Ant. 8, 331 <span class=\"greek\">πυθ</span>. <span class=\"greek\">τίς</span> <span class=\"greek\">εἴη</span>; BGU 893, 26 <span class=\"greek\">ἐπύθετο</span>, <span class=\"greek\">πόσον</span> <span class=\"greek\">ἔχει</span>; POxy 1063, 6) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.15.26\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 15:26</a>; 18:36; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.13.24\" target=\"_blank\" rel=\"noopener noreferrer\">J 13:24</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 21:33</a>. <span class=\"greek\">π</span>. <span class=\"greek\">εἰ</span> seguido de indic. indagar se … 10:18 (v. 2 Macc 3:9; Jos., Ant. 10, 259). <span class=\"greek\">π</span>. <span class=\"greek\">παρά</span> <span class=\"greek\">τινος</span> seguido de pergunta indireta (Lucian, Nigr. 1; Jos., Vi. 258, Ant. 16, 328) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.2.4\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 2:4</a>. Seguido de pergunta direta (Plut., Demetr. 901 [27, 9]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.4.7\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 4:7</a>; 10:29; 23:19.</p><p class=\"entry-text\">② averiguar algo mediante indagação, ficar sabendo mediante indagação, seguido de <span class=\"greek\">ὅτι</span> (X., An. 6, 3, 23; PHamb 27, 7 [III a.C.] <span class=\"greek\">πυνθανόμενος</span> <span class=\"greek\">αὐτοῦ</span>, <span class=\"greek\">ὅτι</span> <span class=\"greek\">ἀπῆλθεν</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.23.34\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 23:34</a>. <span class=\"greek\">π</span>. <span class=\"greek\">περί</span> <span class=\"greek\">τινος</span> (Appian, Bell. Civ. 4, 123 §515 <span class=\"greek\">περὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">λιμοῦ</span>) seguido de pergunta indireta Dg 1.—DELG. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-05\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυξίς, ίδος, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυξίς</span>, <span class=\"greek\">ίδος</span>, <span class=\"greek\">ἡ</span> primariamente ‘caixa’ feita de madeira de buxo, depois qualquer espécie de caixa, especialmente como recipiente para medicamentos (Lucian, Philops. 21; Galen XIII 743 K.; Jos., Bell. 1, 598; BGU 1300, 8 [III/II a.C.]; PRyl 125, 26f [I d.C.]; Sb 4324, 17), em nossa literatura acerca de um recipiente para veneno (como Jos., Bell. 1, 598, Ant. 17, 77) caixa, recipiente Hv 3, 9, 7.—Frisk s.v. <span class=\"greek\">πύξος</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-06\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύον, ου, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πύον</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">τό</span> (cf. <span class=\"greek\">πύθομαι</span> ‘decompor-se’; Hippocr. e outros; Antig. Car. 117) pus ApcPt 16:31.—DELG s.v. <span class=\"greek\">πύθομαι</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-07\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πῦρ, ός, τό</h1><div class=\"entry-meta\"><span>substantivo neutro</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πῦρ</span>, <span class=\"greek\">ός</span>, <span class=\"greek\">τό</span> (Hom.+) fogo</p><p class=\"entry-text\">ⓐ acerca do fogo terrestre, como elemento importante na criação Dg 7:2.—<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.17.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 17:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:22</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.5\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:5</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.5.3\" target=\"_blank\" rel=\"noopener noreferrer\">Js 5:3</a> (cf. 4 Macc 15:15); ITr 2:3. Fusão de chumbo 2 Cl 16:3. Necessário para forjar metais Dg 2:3. Prova da pureza de metais preciosos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 1:7</a>; Hv 4, 3, 4; em metáfora <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.3.18\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 3:18</a>. Para <span class=\"greek\">ἄνθρακες</span> <span class=\"greek\">πυρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ROM.12.20\" target=\"_blank\" rel=\"noopener noreferrer\">Ro 12:20</a> v. <span class=\"greek\">ἄνθραξ</span>. Para <span class=\"greek\">κάμινος</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">πυρός</span> (Iren. 5, 5, 2 [Harv. II 332, 2) 1 Cl 45:7; 2 Cl 8:2 v. <span class=\"greek\">κάμινος</span>. Para <span class=\"greek\">βάλλειν</span> <span class=\"greek\">εἰς</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">π</span>. v. <span class=\"greek\">βάλλω</span> 1b.—<span class=\"greek\">περιάπτειν</span> <span class=\"greek\">πῦρ</span> acender um fogo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:55</a>. <span class=\"greek\">κατακαίειν</span> <span class=\"greek\">τι</span> <span class=\"greek\">πυρί</span> queimar (completamente) algo com fogo, numa construção pass. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.40\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:40</a>; <span class=\"greek\">τινὰ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρὶ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.17.16\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 17:16</a> (v.l. sem <span class=\"greek\">ἐν</span>). Construção pass. 18:8. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">κατακαίεσθαι</span> MPol 5:2 (<span class=\"greek\">κατακαίω</span>, fim). <span class=\"greek\">πῦρ</span> <span class=\"greek\">καιόμενον</span> 11:2b (<span class=\"greek\">καίω</span> 1a). <span class=\"greek\">πυρὶ</span> <span class=\"greek\">καίεσθαι</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.18\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:18</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:8</a> (<span class=\"greek\">καίω</span> 1a). O fogo é usado em comparações <span class=\"greek\">γλῶσσαι</span> <span class=\"greek\">ὡσεὶ</span> <span class=\"greek\">πυρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:3</a> (Ezek. Trag. 234 [em Eus., PE 9, 29, 14] <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">φέγγος</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">ὤφθη</span> <span class=\"greek\">ἡμῖν</span>). <span class=\"greek\">φλὸξ</span> <span class=\"greek\">πυρός</span> uma chama de fogo (Ex 3:2; Is 29:6; PsSol 15:4; JosAs 14:9): <span class=\"greek\">ὀφθαλμοὶ</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">φλὸξ</span> <span class=\"greek\">πυρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.14\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:14</a>; cf. 2:18; 19:12.—Acerca de um obreiro cristão que edificou mal na congregação diz-se <span class=\"greek\">σωθήσεται</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πυρός</span> será salvo como que através do fogo, isto é, como uma pessoa que precisa atravessar uma parede de fogo para escapar de uma casa em chamas (Ps.-Crates, Ep. 6 [=Malherbe p. 56] <span class=\"greek\">κἂν</span> <span class=\"greek\">διὰ</span> <span class=\"greek\">πυρός</span>; Jos., Ant. 17, 264 <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span>; Diod S 1, 57, 7; 8 <span class=\"greek\">διὰ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">φλογὸς</span> … <span class=\"greek\">σωθείς</span> de uma tenda em chamas) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.15\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:15</a> (HHollander, NTS 40, ’94, 89–104; v. <span class=\"greek\">σῴζω</span> 3). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.23\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 23</a> (<span class=\"greek\">ἁρπάζω</span> 2a).—Acerca da tortura de um fiel confessor pelo fogo IRo 5:3; ISm 4:2; MPol 2:3; 11:2a; 13:3; 15:1f; 16:1; 17:2; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.11.34\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 11:34</a>; em linguagem figurada acerca de Roma <span class=\"greek\">ἀπέρχομαι</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">κάμινον</span> <span class=\"greek\">πυρός</span> AcPl Ha 6, 20 (cf. b abaixo).</p><p class=\"entry-text\">ⓑ acerca do fogo que é celestial em origem e natureza (cf. Diod S 4, 2, 3 acerca do ‘fogo’ do raio, que acompanha a aparição de Zeus; 16, 63, 3 <span class=\"greek\">τὸ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">πῦρ</span>; Just., D. 88, 3 <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἀνήφθη</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Ἰορδάνῳ</span> [no batismo de Jesus]. Na especulação gnóstica Iren. 1, 17, 1 [Harv. I 164, 14]; Hippol., Ref. 6, 9, 5.—Orig., C. Cels. 4, 13, 19): um anjo aparece a Moisés <span class=\"greek\">ἐν</span> <span class=\"greek\">φλογὶ</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">βάτου</span> na chama de uma sarça ardente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.7.30\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 7:30</a> (v. Ex 3:2; cf. Just., A I, 62, 3 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἰδέᾳ</span> <span class=\"greek\">πυρός</span>.—PKatz, ZNW 46, ’55, 133–38). Deus faz <span class=\"greek\">τοὺς</span> <span class=\"greek\">λειτουργοὺς</span> <span class=\"greek\">αὐτοῦ</span> <span class=\"greek\">πυρὸς</span> <span class=\"greek\">φλόγα</span> (cf. Ps 103:4, especialmente na v.l. [ARahlfs, Psalmi cum Odis ’31]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 1:7</a>; 1 Cl 36:3. Correspondentemente, diante do trono celestial ardem sete <span class=\"greek\">λαμπάδες</span> <span class=\"greek\">πυρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.4.5\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 4:5</a> e o ‘anjo forte’ 10:1 tem <span class=\"greek\">πόδες</span> <span class=\"greek\">ὡς</span> <span class=\"greek\">στῦλοι</span> <span class=\"greek\">πυρός</span>, mas ambas as passagens se enquadram igualmente bem em a. O fogo aparece sobretudo como meio empregado por Deus para executar o castigo: no passado, no caso de Sodoma <span class=\"greek\">ἔβρεξεν</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">θεῖον</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.17.29\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 17:29</a> (Gen 19:24; cf. 1QH 3:31). Cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.9.54\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 9:54</a> (4 Km 1:10, 12; TestAbr A 10 p. 88, 13 [Stone p. 24, 13] <span class=\"greek\">ἐξ</span> <span class=\"greek\">οὐρανοῦ</span>; Jos., Ant. 9, 23 <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">οὐρανοῦ</span> <span class=\"greek\">πεσόν</span>). De modo marcadamente predominante em conexão com o Juízo Final: o fim do mundo <span class=\"greek\">δι</span>’ <span class=\"greek\">αἵματος</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πυρός</span> Hv 4, 3, 3; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.19\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:19</a> (Jo 3:3. Também Sib-Or 4, 173; 5, 376f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.8.7\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 8:7</a>. <span class=\"greek\">κόσμος</span> <span class=\"greek\">αἴρεται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρί</span> AcPl Ha 2, 26; 9, 11. O Dia do Juízo <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρὶ</span> <span class=\"greek\">ἀποκαλύπτεται</span> manifesta-se com fogo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.13\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:13a</a>; cf. 13b (JGnilka, Ist <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 3:10–15</a> … Fegfeuer? ’55); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.7\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:7</a> (sobre as concepções cosmológicas do primeiro século v. FDowning, L’AntCl 64, ’95, 99–109, especialmente 107f). Quando Jesus voltar, manifestar-se-á com seus anjos <span class=\"greek\">ἐν</span> <span class=\"greek\">πυρὶ</span> <span class=\"greek\">φλογός</span> (cf. Sir 45:19) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2TH.1.8\" target=\"_blank\" rel=\"noopener noreferrer\">2 Th 1:8</a>. Frequentemente em Rv: o fogo é lançado do céu sobre a terra 8:5; 13:13; 20:9 (<span class=\"greek\">καταβαίνω</span> 1b). Procede da boca das duas testemunhas de Deus 11:5 e da boca dos cavalos portadores de pragas 9:17f. V. 16:8. Para <span class=\"greek\">πυρὸς</span> <span class=\"greek\">ζῆλος</span> <span class=\"greek\">ἐσθίειν</span> <span class=\"greek\">μέλλοντος</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ὑπεναντίους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.10.27\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 10:27</a> v. <span class=\"greek\">ζῆλος</span> 1, fim. <span class=\"greek\">ἡ</span> <span class=\"greek\">χείρ</span> <span class=\"greek\">μου</span> <span class=\"greek\">πυρὶ</span> <span class=\"greek\">ἀποπίπτει</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐμοῦ</span> minha mão desprende-se de mim por causa do fogo (por estar ardendo nele) GJs 20:1 (códices).—O fogo com que Deus castiga os pecadores (cf. ApcSed 4:1 <span class=\"greek\">κόλασις</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἐστιν</span> <span class=\"greek\">ἡ</span> <span class=\"greek\">παίδευσίς</span> <span class=\"greek\">σου</span>) <span class=\"greek\">οὐ</span> <span class=\"greek\">σβέννυται</span> (cf. Is 66:24) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.48\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:48</a>; 2 Cl 7:6; 17:5. Por isso é chamado (v. PGM 5, 147 <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἀθάνατον</span>): (<span class=\"greek\">τὸ</span>) <span class=\"greek\">πῦρ</span> (<span class=\"greek\">τὸ</span>) <span class=\"greek\">αἰώνιον</span> (4 Macc 12:12; TestZeb 10:3; GrBar 4:16; Just., A I, 21, 6 e outros; Tat. 17, 1; Theoph. Ant. 1, 14 [p. 92, 9]) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.18.8\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 18:8</a>; 25:41; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JUD.1.7\" target=\"_blank\" rel=\"noopener noreferrer\">Jd 7</a>; Dg 10:7 (oposto a <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">πρόσκαιρον</span> 10:8). <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἄσβεστον</span> (<span class=\"greek\">ἄσβεστος</span> 1) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:12</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.43\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:43</a>, 45 v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.17\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:17</a>; 2 Cl 17:7; IEph 16:2; AcPl Ha 1, 22. Arde na <span class=\"greek\">γέεννα</span> (<span class=\"greek\">τοῦ</span>) <span class=\"greek\">πυρός</span> (ApcEsdr 1:9 p. 25, 1 Tdf.; v. <span class=\"greek\">γέεννα</span> e cf. En 10:13 <span class=\"greek\">τὸ</span> <span class=\"greek\">χάος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.5.22\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 5:22</a>; 18:9 (cf. 1QS 2:7f); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.47\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:47</a> v.l.; 2 Cl 5:4 (um dito de Jesus não registrado em outro lugar). <span class=\"greek\">ἡ</span> <span class=\"greek\">λίμνη</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρὸς</span> (<span class=\"greek\">καὶ</span> <span class=\"greek\">θείου</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.19.20\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 19:20</a>; 20:10, 14ab, 15 (cf. Jos As 12, 10 <span class=\"greek\">ἄβυσσον</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span>); cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.21.8\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 21:8</a>; 14:10, 18; 15:2. O lugar de castigo pelo fogo, designado como <span class=\"greek\">ἡ</span> <span class=\"greek\">κάμινος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.13.42\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 13:42</a>, 50 (diferentemente AcPl Ha 6, 20 v. no fim de a, acima). <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἐστι</span> <span class=\"greek\">μετ</span>’ <span class=\"greek\">αὐτοῦ</span> o fogo aguarda essa pessoa AcPlCor 2:37. O fogo do inferno também é referido em certas parábolas e alegorias nas quais árvores e videiras representam pessoas merecedoras de castigo <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.10\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:10</a>; 7:19; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.9\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:9</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.15.6\" target=\"_blank\" rel=\"noopener noreferrer\">J 15:6</a>. Aquele cuja vinda foi proclamada por João Batista <span class=\"greek\">βαπτίσει</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">πνεύματι</span> <span class=\"greek\">ἁγίῳ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">πυρί</span>; é discutível se <span class=\"greek\">πῦρ</span> em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.3.11\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 3:11</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a> se refere ao recebimento do Espírito Santo (especialmente em <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.3.16\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 3:16</a>) ou ao fogo do juízo divino; para a associação de <span class=\"greek\">πῦρ</span> com <span class=\"greek\">πνεῦμα</span> v. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.2.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 2:3f</a>; AcPlCor 2:13 (<span class=\"greek\">βαπτίζω</span> 3b). Como Senhor do Juízo, Deus é chamado <span class=\"greek\">πῦρ</span> <span class=\"greek\">καταναλίσκον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/HEB.12.29\" target=\"_blank\" rel=\"noopener noreferrer\">Hb 12:29</a> (Dt 4:24; 9:3.—Mesomedes chama Ísis <span class=\"greek\">πῦρ</span> <span class=\"greek\">τέλεον</span> <span class=\"greek\">ἄρρητον</span> [IAndrosIsis p. 145, 14]).—De natureza diferente é a ideia de que o fogo deve ser adorado como um deus (Maximus Tyr. 2, 4b acerca dos persas: <span class=\"greek\">πῦρ</span> <span class=\"greek\">δέσποτα</span>; Theosophien 14 p. 170, 11 <span class=\"greek\">τὸ</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἀληθῶς</span> <span class=\"greek\">θεός</span>) Dg 8:2.</p><p class=\"entry-text\">ⓒ fig. (Just., D. 8, 1 <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῇ</span> <span class=\"greek\">ψυχῇ</span> <span class=\"greek\">ἀνήφθη</span>; Chariton 2, 4, 7 <span class=\"greek\">πῦρ</span> <span class=\"greek\">εἰς</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχήν</span>; Ael. Aristid. 28, 110 K.=49 p. 527 D.: <span class=\"greek\">τὸ</span> <span class=\"greek\">ἱερὸν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">θεῖον</span> <span class=\"greek\">πῦρ</span> <span class=\"greek\">τὸ</span> <span class=\"greek\">ἐκ</span> <span class=\"greek\">Διός</span>; Aristaen., Ep. 2, 5; PGrenf I=Coll. Alex. p. 177 linha 15 [II a.C.] acerca do fogo do amor; Theoph. Ant. 1, 3 [p. 62, 21] acerca da ira de Deus) <span class=\"greek\">ἡ</span> <span class=\"greek\">γλῶσσα</span> <span class=\"greek\">πῦρ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JAS.3.6\" target=\"_blank\" rel=\"noopener noreferrer\">Js 3:6</a> (v. <span class=\"greek\">γλῶσσα</span> 1a). O dito de Jesus <span class=\"greek\">πῦρ</span> <span class=\"greek\">ἦλθον</span> <span class=\"greek\">βαλεῖν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τὴν</span> <span class=\"greek\">γῆν</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.12.49\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 12:49</a> parece, no contexto em que agora se encontra, referir-se ao fogo da discórdia (v. vv. 51–53). <span class=\"greek\">πῦρ</span> também é entendido figuradamente em Agr 3, cujo sentido, entretanto, não pode ser determinado com certeza (v. Unknown Sayings, 54–56) <span class=\"greek\">ὁ</span> <span class=\"greek\">ἐγγύς</span> <span class=\"greek\">μου</span> <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span>. <span class=\"greek\">ὁ</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">ἀπ</span>’ <span class=\"greek\">ἐμοῦ</span> <span class=\"greek\">μακρὰν</span> <span class=\"greek\">ἀπὸ</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">βασιλείας</span> (cf. <span class=\"greek\">ἐγγύς</span> 3; <span class=\"greek\">ἐγγὺς</span> <span class=\"greek\">εἶναι</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυρός</span> como algo perigoso também Chariton 6, 3, 9). Sobre a difícil passagem <span class=\"greek\">πᾶς</span> <span class=\"greek\">πυρὶ</span> <span class=\"greek\">ἁλισθήσεται</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:49</a> e suas variantes v. <span class=\"greek\">ἁλίζω</span> e cf. <span class=\"greek\">ἅλας</span> b (v. também NColeman, JTS 24, 1923, 381–96, ET 48, ’37, 360–62; PHaupt, Salted with Fire: AJP 45, 1924, 242–45; AFridrichsen, Würzung durch Feuer: SymbOsl 4, 1926, 36–38; JdeZwaan, Met vuur gezouten worden, Mc 9:49: NThSt 11, 1928, 179–82; RHarris, ET 48, ’37, 185f; SEitrem, Opferritus u. Voropfer der Griechen u. Römer 1915, 309–44. JBauer, TZ 15, ’59, 446–50; HZimmermann [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:49</a>], TQ 139, ’59, 28–39; TBaarda [<a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.9.49\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 9:49</a>], NTS 5, ’59, 318–21).—B. 71; RAC VII 786–90; BHHW I 479f. DELG. M-M. EDNT. TW. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-08\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πῦρ</span>; Hom. e outros; PGM 4, 32; LXX; Philo, Conf. Lingu. 157; SibOr 8, 494) em nossa literatura somente acerca de um monte de material combustível ou mesmo em combustão, uma fogueira <span class=\"greek\">ἅπτειν</span> <span class=\"greek\">πυράν</span> (Hdt. 1, 86; 2 Macc 10:36) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.2\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:2</a>; cf. <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.22.55\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 22:55</a> v.l.; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.3\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:3</a>.—Uma pira na qual alguém é queimado (acerca de Creso: Hdt. 1, 86, 2ff; Ep. 56 de Apolônio de Tiana [Philostrat. I 359, 13]; acerca de Calano, o sábio da Índia: Arrian, Anab. 7, 3, 4ff; acerca de César: Just., A I, 21, 3; acerca de Héracles: Ath. 29, 1): acerca de um fiel confessor MPol 13:2f.—DELG s.v. <span class=\"greek\">πύρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-09\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύργος, ου, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πύργος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (Hom.+ [um empréstimo nórdico: PKretschmer, Glotta 22, ’34, 100ff]; empréstimo na literatura rabínica).</p><p class=\"entry-text\">① construção alta usada como posto de observação, torre <span class=\"greek\">ὁ</span> <span class=\"greek\">πύργος</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">τῷ</span> <span class=\"greek\">Σιλωάμ</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.13.4\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 13:4</a> (Demetr. de Calátis [200 a.C.]: 85 Fgm. 6 Jac. <span class=\"greek\">πεσόντος</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πύργου</span> <span class=\"greek\">πεσεῖν</span> <span class=\"greek\">κ</span>. <span class=\"greek\">αὐτάς</span> [=25 moças]). Acerca de torres como as construídas numa vinha para vigias (BGU 650, 8 [60/61 d.C.]: Is 5:2) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.21.33\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 21:33</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.12.1\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 12:1</a>; provavelmente também <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:28</a> (mas v. 2 abaixo e v. C-HHunzinger, ZNW Beiheft 26, ’60, 211–17 [Evangelho de Tomé]).—B 16:5 (citação da Escritura, presumivelmente de En 89:56). Em Hermas a comunidade cristã é representada como uma torre (cf. SibOr 5, 424; Leutzsch, Hermas 410–12 n. 282) Hv 3; 4, 3, 4; Hs 8 e 9 (mais de 145 vezes).</p><p class=\"entry-text\">② edifício em forma de torre, construção agrícola (v. FPreisigke, Her 54, 1919, 93; EMeyer, Her. 55, 1920, 100; AAlt, ibid. 334–36; JHasebroek, Her 57, 1922, 621–23; PMeyer, Ztschr. für vergleichende Rechtswissenschaft 40, 1922, 207. Rejeitado por WCrönert, Gnomon 4, 1928, 80) assim possivelmente <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.14.28\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 14:28</a> (mas v. 1 acima).—DELG. M-M. TW. Spicq. Sv.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-10\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρέσσω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρέσσω</span> (v. verbete seguinte; Eur., Hippocr. e outros; Epict. [v. índice Sch.]; M. Ant. 8, 15; Diog. L. 6, 1, 6; Jos., Vi. 404; POslo 95, 20 [96 d.C.]; 152, 4) sofrer de febre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.14\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:14</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.30\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:30</a>.—DELG s.v. <span class=\"greek\">πύρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-11\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρετός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρετός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (<span class=\"greek\">πῦρ</span>, v. verbete anterior) febre ([Il. 22, 31 ‘calor ardente’]; Aristoph.; Hippocr.; SIG 1239, 20; 1240, 12; IDefixAudollent 74, 6; BGU 956, 2; POxy 924, 6; 1151, 35; Dt 28:22; TestSol 18, 20 e 23; Philo; Jos., Vi. 48) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.39\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:39</a>. <span class=\"greek\">ἀφῆκεν</span> <span class=\"greek\">αὐτὴν</span> (<span class=\"greek\">αὐτὸν</span>) <span class=\"greek\">ὁ</span> <span class=\"greek\">πυρετός</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.8.15\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 8:15</a>; <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MRK.1.31\" target=\"_blank\" rel=\"noopener noreferrer\">Mk 1:31</a> (JCook, NTS 43, ’97, 184–208); <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/JHN.4.52\" target=\"_blank\" rel=\"noopener noreferrer\">J 4:52</a>. Nas duas passagens seguintes <span class=\"greek\">πυρ</span>. é usado com <span class=\"greek\">συνέχεσθαι</span> (cf. Diod S 36, 13, 3 <span class=\"greek\">παραχρῆμα</span> <span class=\"greek\">πυρετῷ</span> <span class=\"greek\">συνεσχέθη</span>; Jos., Ant. 13, 398 <span class=\"greek\">πυρετῷ</span> <span class=\"greek\">συσχεθείς</span>; POxy 986, 33 <span class=\"greek\">ὄντα</span> <span class=\"greek\">πυρετίοις</span> <span class=\"greek\">συνεχόμενον</span>), pl. (Demosth. e outros; Hippocr.: CMG I/1 p. 40, 1; 50, 6; com <span class=\"greek\">δυσεντερία</span> p. 57, 27f; 60, 27) <span class=\"greek\">πυρετοῖς</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">δυσεντερίῳ</span> <span class=\"greek\">συνεχόμενον</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.28.8\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 28:8</a>. <span class=\"greek\">συνεχομένη</span> <span class=\"greek\">πυρετῷ</span> <span class=\"greek\">μεγάλῳ</span> sofrendo de um acesso intenso de febre <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/LUK.4.38\" target=\"_blank\" rel=\"noopener noreferrer\">Lk 4:38</a> (cf. Diod S 32, 10, 3 <span class=\"greek\">τῶν</span> <span class=\"greek\">πυρετῶν</span> <span class=\"greek\">μεγάλων</span> <span class=\"greek\">συνεπιγινομένων</span>; Galen, De Diff. Febr. 1, 1 vol. VII 275 Kühn <span class=\"greek\">σύνηθες</span> <span class=\"greek\">τοῖς</span> <span class=\"greek\">ἰατροῖς</span> <span class=\"greek\">ὀνομάζειν</span> <span class=\"greek\">τὸν</span> <span class=\"greek\">μέγαν</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μικρὸν</span> <span class=\"greek\">πυρετόν</span>; Alexander de Afrodísias, De Febribus Libell. 31 [JIdeler, Physici et Medici Graeci Minores I 1841, 105f] <span class=\"greek\">μικρούς</span> <span class=\"greek\">τε</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μεγάλους</span> <span class=\"greek\">ὀνομάζομεν</span> <span class=\"greek\">πυρετούς</span>; Aulus Cornel. Celsus 4, 14 magnae febres.—V. sobre isso JSchuster, M.D., BZ 13, 1915, 338ff; HCadbury, JBL 45, 1926, 194f; 203; 207 nota); GDunst, ZPE 3, ’68, 148–53 (culto da febre); WKirchschläger, Fieberheilung in Apg 28 und Lk 4: Les Actes des Apôtres etc., ed. JKremer ’79, 509–21. Sobre a febre no mundo greco-romano v. também PBurke, ANRW II Principat 37/3 ’96, 2252–81.—DELG s.v. <span class=\"greek\">πύρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-12\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρινος, η, ον</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πύρινος</span>, <span class=\"greek\">η</span>, <span class=\"greek\">ον</span> da cor do fogo, ígneo (Aristot. e outros; Kaibel 987 [95 d.C.]; PTebt 1, 16 [I a.C.]; BGU 590, 1; PGM 4, 589; Sir 48:9 <span class=\"greek\">ἐν</span> <span class=\"greek\">ἅρματι</span> <span class=\"greek\">ἵππων</span> <span class=\"greek\">πυρίνων</span>; Ezk 28:14, 16; En 14:11; TestAbr A; ApcEsdr 4:9 p. 28, 8 Tdf. [<span class=\"greek\">θρόνος</span>] e outros) <span class=\"greek\">ἀκρίδες</span> <span class=\"greek\">πύριναι</span> gafanhotos ígneos Hv 4, 1, 6. Cavaleiros espectrais vestem <span class=\"greek\">θώρακας</span> <span class=\"greek\">πυρίνους</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.9.17\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 9:17</a> (SibOr 3, 673 <span class=\"greek\">ῥομφαῖαι</span> <span class=\"greek\">πύριναι</span>).—DELG s.v. <span class=\"greek\">πύρ</span>. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-13\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρκαϊά, ᾶς, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρκαϊά</span>, <span class=\"greek\">ᾶς</span>, <span class=\"greek\">ἡ</span> (Hom. e outros; Trag., Hdt., Aristot.) pira funerária MPol 13:2 v.l. (em lugar de <span class=\"greek\">πυρά</span>).—DELG s.v. <span class=\"greek\">καίω</span> 10; <span class=\"greek\">πύρ</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-14\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυροειδής, ές</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυροειδής</span>, <span class=\"greek\">ές</span> (sobre a formação v. Schwyzer I 440—Pla., Leg. 10, 895c e outros; Cleanthes: Stoic. Fgm. 506 e outros. Comp. <span class=\"greek\">πυρωδέστερος</span> Just., D. 121, 2; Cat. Cod. Astr. IX/2 p. 119, 5 acerca de <span class=\"greek\">φῶς</span>) da cor do fogo, vermelho como fogo=vermelho vivo (com <span class=\"greek\">αἱματώδης</span>, v. esse verbete) Hv 4, 1, 10; 4, 3, 3.—V. <span class=\"greek\">αἷμα</span> 3; Leutzsch, Hermas 434f n. 507.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-15\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρός, οῦ, ὁ</h1><div class=\"entry-meta\"><span>substantivo masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρός</span>, <span class=\"greek\">οῦ</span>, <span class=\"greek\">ὁ</span> (sobre a formação v. Schwyzer I 58; talvez relacionado a <span class=\"greek\">πυρήν</span> ‘caroço’ de um fruto, v. Boisacq 829—Hom., Hdt., Aristoph. e outros; pap., LXX; TestJud 9:8; EpArist 145; Philo; Tat. 9, 2) trigo <span class=\"greek\">τὸν</span> <span class=\"greek\">ἐπὶ</span> <span class=\"greek\">τοῦ</span> <span class=\"greek\">πυροῦ</span> <span class=\"greek\">σπόρον</span> semeadura de trigo AcPlCor 2:26.—DELG s.v. <span class=\"greek\">πυρός</span>.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-16\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρόω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρόω</span> fut. <span class=\"greek\">πυρώσω</span> LXX; 1 aor. <span class=\"greek\">ἐπύρωσα</span> LXX. Pass.: 1 aor. <span class=\"greek\">ἐπυρώθην</span>; part. perf. <span class=\"greek\">πεπυρωμένος</span> (Pind. e outros; ins., LXX, Philo) primariamente como ativo ‘queimar algo com fogo’, em nossa literatura somente pass. (Ps.-Pla., Axioch. 372a acerca dos tormentos no Tártaro; Philo).</p><p class=\"entry-text\">① fazer arder, queimar</p><p class=\"entry-text\">ⓐ lit., acerca do fim ígneo do mundo <span class=\"greek\">οὐρανοὶ</span> <span class=\"greek\">πυρούμενοι</span> <span class=\"greek\">λυθήσονται</span> os céus serão incendiados e dissolvidos <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2PE.3.12\" target=\"_blank\" rel=\"noopener noreferrer\">2 Pt 3:12</a>. Em linguagem figurada <span class=\"greek\">τὰ</span> <span class=\"greek\">βέλη</span> <span class=\"greek\">τὰ</span> <span class=\"greek\">πεπυρωμένα</span> (v. <span class=\"greek\">βέλος</span>) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/EPH.6.16\" target=\"_blank\" rel=\"noopener noreferrer\">Eph 6:16</a> (v. Cicero, Tusc. Disp. 5, 27, 76).</p><p class=\"entry-text\">ⓑ fig. (ativo Cornutus 25 p. 47, 11 <span class=\"greek\">πυροῦν</span> <span class=\"greek\">τ</span>. <span class=\"greek\">ψυχάς</span>; pass., Horapollo 1, 22 <span class=\"greek\">ἡ</span> <span class=\"greek\">καρδία</span> <span class=\"greek\">πυροῦται</span>) arder, inflamar-se de compaixão, disposição para ajudar ou indignação <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/2CO.11.29\" target=\"_blank\" rel=\"noopener noreferrer\">2 Cor 11:29</a> (cf. 2 Macc 4:38; 10:35; 14:45; 3 Macc 4:2; Philo, Leg. All. 1, 84 <span class=\"greek\">πεπύρωται</span> <span class=\"greek\">ἐν</span> <span class=\"greek\">εὐχαριστίᾳ</span> <span class=\"greek\">θεοῦ</span>. Assim provavelmente também a inscrição judaico-grega de Tell el Yehudieh ed. Ltzm. [ZNW 22, 1923, 282] 18, 5 <span class=\"greek\">πατὴρ</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">μήτηρ</span> <span class=\"greek\">οἱ</span> <span class=\"greek\">πυρώμενοι</span>=‘pai e mãe, que ardem de pesar’; cf. Sb 6646; 6659; Ltzm. pensa na cremação dos mortos e remete a 20, 4, mas ali é usado o ativo); arder de desejo sexual <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1CO.7.9\" target=\"_blank\" rel=\"noopener noreferrer\">1 Cor 7:9</a> (sobre o assunto cf. Hos 7:4; Sir 23:17; para uma expressão poética do desejo ardente v. Anacreontea 11, 15 Preis.: <span class=\"greek\">Ἔρως</span> <span class=\"greek\">εὐθέως</span> <span class=\"greek\">με</span> <span class=\"greek\">πύρωσον</span>; cf. Sappho Fgm. 36 e 48; tema comum em papiros mágicos, p. ex. PGM 4, 2931 <span class=\"greek\">βάλε</span> <span class=\"greek\">πυρσὸν</span> <span class=\"greek\">ἔρωτα</span>; 36, 111; 200 <span class=\"greek\">πυρουμένη</span>; PBerlin 9909, 48; cf. Plut., Mor. 138f; 752d; 753a e outros.—SGordon, ET 21, 1910, 478f).</p><p class=\"entry-text\">② fazer ficar muito quente, tornar rubro de calor, tornar incandescente, aquecer intensamente (Lucian, Alex. 21 <span class=\"greek\">βελόνην</span>) acerca de metais <span class=\"greek\">πεπυρωμένον</span> <span class=\"greek\">σίδηρον</span> APt 13:28. Por tal aquecimento os metais preciosos são provados e refinados (Job 22:25; Ps 11:7; 65:10; Pr 10:20) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.1.15\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 1:15</a> (<span class=\"greek\">πεπυρωμένης</span> é uma das peculiaridades linguísticas de Rv [v. <span class=\"greek\">καὶ</span> <span class=\"greek\">ἔχων</span>, que vem logo depois]. Todas as variantes [-<span class=\"greek\">μένῳ</span>,-<span class=\"greek\">μένοι</span>] aqui são simplesmente tentativas de corrigir a expressão; sobre a relação com o aramaico v. Mussies 98f. FRehkopf, JJeremias Festschr. ’70, 214–19); 3:18; MPol 15:2.—Hv 4, 3, 4 estabelece uma comparação entre a influência refinadora do fogo sobre os metais e o efeito que as provas de fogo têm na remoção de impurezas dos cristãos.—DELG s.v. <span class=\"greek\">πύρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-17\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρράζω</h1><div class=\"entry-meta\"><span>verbo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρράζω</span> (v. verbete seguinte; também <span class=\"greek\">πυράζω</span> somente em escritores bizantinos [Psaltes 332]; a LXX tem <span class=\"greek\">πυρρίζω</span>) ser vermelho (como fogo), acerca da cor do céu matutino ou vespertino <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/MAT.16.2\" target=\"_blank\" rel=\"noopener noreferrer\">Mt 16:2f</a>.—M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-18\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πυρρός, ά, όν</h1><div class=\"entry-meta\"><span>adjetivo</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πυρρός</span>, <span class=\"greek\">ά</span>, <span class=\"greek\">όν</span> (v. verbete anterior; Aeschyl., Hdt.+; ins., pap., LXX; En 18:7. Sobre o <span class=\"greek\">ρ</span> duplo v. B-D-F §34, 2; Mlt-H. 101) vermelho como fogo, como a cor apocalíptica de um cavalo (Theocr. 15, 53, acerca de uma raposa erguida sobre as patas traseiras) <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.6.4\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 6:4</a> (<span class=\"greek\">τὸ</span> <span class=\"greek\">λευκόν</span>, <span class=\"greek\">μέλαν</span>, <span class=\"greek\">ἐρυθρόν</span>, <span class=\"greek\">χλωρόν</span> são as quatro cores básicas [Theophr., Sens. 13, 73–75]. Em Rv, provavelmente devido à influência do <span class=\"greek\">ἵππος</span> <span class=\"greek\">πυρρός</span> de Zech 1:8 e 6:2, a palavra <span class=\"greek\">ἐρ</span>. foi mudada para seu equivalente prático <span class=\"greek\">πυρρ</span>.—Cf. Petosiris, Fgm. 12 linha 25f: <span class=\"greek\">μέλας</span> … <span class=\"greek\">λοιμὸν</span> [melhor <span class=\"greek\">λιμὸν</span> segundo a linha 187] <span class=\"greek\">ποιεῖ</span>, <span class=\"greek\">χλωρὸς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">νόσους</span>, <span class=\"greek\">πυρρὸς</span> <span class=\"greek\">δὲ</span> <span class=\"greek\">πόλεμον</span> <span class=\"greek\">καὶ</span> <span class=\"greek\">σφαγάς</span>. RGradwohl, D. Farben im AT, Beih. ZAW 83, ’63, 8). Acerca de um dragão <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.12.3\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 12:3</a> (em Diod S 1, 88, 4 <span class=\"greek\">π</span>. é a cor de Tífon, inimigo dos deuses. Cf. também Phlegon: 257 Fgm. 36, 3, 11 Jac. <span class=\"greek\">ὑπὸ</span> <span class=\"greek\">λύκου</span> <span class=\"greek\">πυρροῦ</span> <span class=\"greek\">εὐμεγέθους</span> <span class=\"greek\">καταβρωθῆναι</span>=ser devorado por um enorme lobo vermelho). Em linguagem figurada acerca dos pecados <span class=\"greek\">πυρρότεραι</span> <span class=\"greek\">κόκκου</span> mais vermelhos que o escarlate 1 Cl 8:3 (citação de origem desconhecida).—Para a literatura v. <span class=\"greek\">αἷμα</span> 3.—DELG s.v. <span class=\"greek\">πύρ</span>. M-M. TW.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-19\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">Πύρρος, ου, ὁ</h1><div class=\"entry-meta\"><span>nome próprio masculino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">Πύρρος</span>, <span class=\"greek\">ου</span>, <span class=\"greek\">ὁ</span> (literatura grega; ins., pap.) Pirro, pai de Sópatro de Bereia; Sópatro acompanhou Paulo quando este levou a coleta a Jerusalém <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/ACT.20.4\" target=\"_blank\" rel=\"noopener noreferrer\">Ac 20:4</a>.—LGPN I. M-M.</p></section></article>\n<article class=\"entry-card\" id=\"entry-bdag-0312-20\" data-dictionary=\"grego\" hidden data-source=\"BDAG\"><header class=\"entry-header\"><div><h1 class=\"entry-title greek\">πύρωσις, εως, ἡ</h1><div class=\"entry-meta\"><span>substantivo feminino</span></div></div><div class=\"source-tag\">BDAG</div></header><div class=\"entry-divider\"></div><section class=\"entry-section\"><div class=\"section-title\">Tradução integral</div><p class=\"entry-text\"><span class=\"greek\">πύρωσις</span>, <span class=\"greek\">εως</span>, <span class=\"greek\">ἡ</span> (<span class=\"greek\">πυρόω</span>; Aristot., Theophr. e outros; PGM 2, 110; Am 4:9; TestSol 18:29 P; TestJud 16:1; Just., D. 116, 2)</p><p class=\"entry-text\">① processo de queimar, combustão (Jos., Ant. 1, 203) lit. em sentido pass. <span class=\"greek\">τὸν</span> <span class=\"greek\">καπνὸν</span> <span class=\"greek\">τῆς</span> <span class=\"greek\">πυρώσεως</span> <span class=\"greek\">αὐτῆς</span> <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/REV.18.9\" target=\"_blank\" rel=\"noopener noreferrer\">Rv 18:9</a>, 18.</p><p class=\"entry-text\">② grau elevado de intensidade de algum acontecimento ou experiência dolorosa, provação ardente, extensão fig. de 1 <span class=\"greek\">ἡ</span> <span class=\"greek\">π</span>. <span class=\"greek\">τῆς</span> <span class=\"greek\">δοκιμασίας</span> a prova de fogo D 16:5. <span class=\"greek\">π</span>. <span class=\"greek\">πρὸς</span> <span class=\"greek\">πειρασμὸν</span> <span class=\"greek\">γινομένη</span> provação ardente para vos pôr à prova <a class=\"reference reference-link\" href=\"https://www.die-bibel.de/en/bible/NA28/1PE.4.12\" target=\"_blank\" rel=\"noopener noreferrer\">1 Pt 4:12</a> (cf. a <span class=\"greek\">πύρωσις</span> para provar metais Pr 27:21). Neste sentido o foco recai sobre o grau de intensidade da provação, mas um componente de sofrimento é indicado pelo contexto, e alguns prefeririam traduzir: sofrimento intenso.—DELG s.v. <span class=\"greek\">πύρ</span>. M-M. TW.</p></section></article>"};
